package dev.thefoolish.generated.makeananimeapplikemihonit;
public final class PlayerActivity extends GeneratedScreen { protected void render(){String id=getIntent().getStringExtra("id");String title=getIntent().getStringExtra("title");int ep=getIntent().getIntExtra("episode",1);String key="progress_"+id+"_"+ep;body.addView(text((title==null?"Anime":title)+" · Episode "+ep,22,true));body.addView(text("Playback surface placeholder. A trusted stream resolver can be connected through the provider boundary.",14,false));body.addView(text("Resume position: "+store.number(key)+" seconds",14,false));Button simulate=action("Save +60 seconds progress");simulate.setOnClickListener(v->{store.number(key,store.number(key)+60);store.putText("last_episode",(title==null?"Anime":title)+" episode "+ep);recreate();});body.addView(simulate);} }
